import java.io.File;
import java.io.IOException;

public class FileMetadataDemo {
    public static void main(String[] args) throws IOException {
        File configDir = new File("config");

        // Create directory if it doesn't exist
        if (!configDir.exists()) {
            configDir.mkdir();  // returns boolean, doesn't throw
        }

        File configFile = new File(configDir, "app.properties");

        // Create empty file
        if (configFile.createNewFile()) {  // throws IOException if fails
            System.out.println("Created: " + configFile.getAbsolutePath());
        }

        // Check metadata
        System.out.println("Exists: " + configFile.exists());
        System.out.println("Is file: " + configFile.isFile());
        System.out.println("Size: " + configFile.length() + " bytes");
        System.out.println("Can read: " + configFile.canRead());

        // List files in directory
        File[] files = configDir.listFiles();
        for (File f : files) {
            System.out.println("Found: " + f.getName());
        }
    }
}

import java.nio.file.*;
import java.io.IOException;
import java.util.Comparator;

public class FileOperationsDemo {
    public static void main(String[] args) throws IOException {
        Path configDir = Path.of("config", "app");
        Path configFile = configDir.resolve("settings.json");

        // Create nested directories (like mkdir -p)
        Files.createDirectories(configDir);
        System.out.println("Created: " + configDir);

        // Create file only if it doesn't exist
        if (!Files.exists(configFile)) {
            Files.createFile(configFile);  // throws if already exists
            System.out.println("Created file: " + configFile);
        }

        // Check file properties
        System.out.println("Exists: " + Files.exists(configFile));
        System.out.println("Is regular file: " + Files.isRegularFile(configFile));
        System.out.println("Is directory: " + Files.isDirectory(configDir));

        // Delete file (throws if doesn't exist)
        Files.delete(configFile);

        // Delete non-empty directory recursively
        Files.walk(configDir)
            .sorted(Comparator.reverseOrder())  // deepest files first
            .forEach(path -> {
                try { Files.delete(path); } 
                catch (IOException e) { e.printStackTrace(); }
            });
    }
}

import java.nio.file.Path;
import java.nio.file.Paths;

public class CrossPlatformPathDemo {
    public static void main(String[] args) {
        // Build paths programmatically - separator handled automatically
        Path baseDir = Path.of("application", "config");
        Path configFile = baseDir.resolve("app.properties");  // safe append

        System.out.println("Config path: " + configFile);
        // Windows: application\config\app.properties
        // Linux:   application/config/app.properties

        // Combine multiple segments
        Path logPath = Path.of("logs", "2024", "01", "app.log");
        System.out.println("Log path: " + logPath);

        // Clean up redundant path elements
        Path messyPath = Path.of("config", "..", "data", ".", "users.json");
        Path cleanPath = messyPath.normalize();  // becomes data/users.json
        System.out.println("Normalized: " + cleanPath);

        // Compute relative path between two locations
        Path from = Path.of("project", "src", "main");
        Path to = Path.of("project", "config", "db.properties");
        Path relative = from.relativize(to);  // ../../config/db.properties
        System.out.println("Relative: " + relative);

        // Resolve relative path against base
        Path resolved = from.resolve(relative);
        System.out.println("Resolved back: " + resolved.normalize());
    }
}
